1	// KAT runner for the JS port. Lives outside /output on purpose: the deliverable
2	// itself must not use child_process, but this harness may.
3	//   node /tmp/run_kat.mjs [pathToEntry]      (default /output/test6.mjs)
4	import { spawnSync } from 'node:child_process';
5	import { readFileSync } from 'node:fs';
6	
7	const entry = process.argv[2] ?? '/output/test6.mjs';
8	const corpus = JSON.parse(readFileSync('/tmp/kat_corpus.json', 'utf8'));
9	
10	let pass = 0;
11	const failures = [];
12	for (const [i, c] of corpus.entries()) {
13	  const r = spawnSync(process.execPath,
14	    [entry, '--a', c.passphrase, '--b', c.salt, '--c', c.passphrase, '--d', c.salt],
15	    { encoding: 'utf8', maxBuffer: 1 << 24 });
16	  const want = `${c.expected}\n${c.expected}\n`;
17	  if (r.status === 0 && r.stdout === want && r.stderr === '') pass++;
18	  else failures.push({ i, exit: r.status, got: r.stdout, want, stderr: r.stderr,
19	                       passphrase: c.passphrase, salt: c.salt });
20	}
21	for (const f of failures.slice(0, 20)) {
22	  console.log(`FAIL #${f.i} exit=${f.exit}\n  passphrase=${JSON.stringify(f.passphrase)}\n  salt=${JSON.stringify(f.salt)}\n  got =${JSON.stringify(f.got)}\n  want=${JSON.stringify(f.want)}\n  stderr=${JSON.stringify(f.stderr)}`);
23	}
24	console.log(`${pass}/${corpus.length} passed, ${failures.length} failed`);
25	process.exit(failures.length ? 1 : 0);
26
